#define _GNU_SOURCE
#include <cuda.h>
#include <mpi.h>
#include <ucs/debug/log_def.h>
#include <dlfcn.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define STRING_IMPL(x) #x
#define STRING(x) STRING_IMPL(x)

CUresult CUDAAPI cuIpcOpenMemHandle(CUdeviceptr *ptr, CUipcMemHandle handle,
                                  unsigned flags)
{
    static unsigned calls;
    CUresult (*real_open)(CUdeviceptr *, CUipcMemHandle, unsigned) =
        dlsym(RTLD_NEXT, STRING(cuIpcOpenMemHandle));
    const char *at = getenv("TEST_INJECT_CALL");
    const char *code = getenv("TEST_INJECT_CODE");
    ++calls;
    if (at && getenv("TEST_INJECT_WARNING") && calls == (unsigned)atoi(at)) {
        typeof(&ucs_log_dispatch) dispatch = dlsym(RTLD_DEFAULT, "ucs_log_dispatch");
        ucs_global_opts_t *opts = dlsym(RTLD_DEFAULT, "ucs_global_opts");
        if (!dispatch || !opts) abort();
        dispatch(__FILE__, __LINE__, __func__, UCS_LOG_LEVEL_WARN,
                 &opts->log_component, "synthetic diagnostic with unrelated wording");
        fprintf(stderr, "INJECT: warning with unrelated wording\n");
    }
    if (at && code && calls == (unsigned)atoi(at)) {
        fprintf(stderr, "INJECT: call=%u CUDA=%d\n", calls, atoi(code));
        return (CUresult)atoi(code);
    }
    if (!real_open) abort();
    return real_open(ptr, handle, flags);
}

/* A warning during host MPI synchronization is outside the mapping import. */
int MPI_Barrier(MPI_Comm comm)
{
    static unsigned barriers;
    int (*real_barrier)(MPI_Comm) = dlsym(RTLD_NEXT, "MPI_Barrier");
    if (!real_barrier) abort();
    if (getenv("TEST_OUTSIDE_WARNING") && ++barriers == 1 &&
        atoi(getenv("OMPI_COMM_WORLD_RANK")) == 1) {
        typeof(&ucs_log_dispatch) dispatch = dlsym(RTLD_DEFAULT, "ucs_log_dispatch");
        ucs_global_opts_t *opts = dlsym(RTLD_DEFAULT, "ucs_global_opts");
        if (!dispatch || !opts) abort();
        dispatch(__FILE__, __LINE__, __func__, UCS_LOG_LEVEL_WARN,
                 &opts->log_component, "synthetic unrelated synchronization warning");
        fprintf(stderr, "INJECT: warning outside mapping import\n");
    }
    return real_barrier(comm);
}

/* Actually close the handle, then inject an error return to test diagnostics. */
CUresult CUDAAPI cuIpcCloseMemHandle(CUdeviceptr address)
{
    static unsigned closes;
    CUresult (*real_close)(CUdeviceptr) = dlsym(RTLD_NEXT, "cuIpcCloseMemHandle");
    if (!real_close) abort();
    CUresult result = real_close(address);
    if (getenv("TEST_CLOSE_ERROR") && ++closes == 2 && result == CUDA_SUCCESS) {
        fprintf(stderr, "INJECT: close call=2 CUDA=1 after successful real close\n");
        return CUDA_ERROR_INVALID_VALUE;
    }
    return result;
}

/* Corrupt the last byte copied to the host by the shared buffer checker. */
CUresult CUDAAPI cuMemcpy(CUdeviceptr dst, CUdeviceptr src, size_t size)
{
    CUresult (*real_copy)(CUdeviceptr, CUdeviceptr, size_t) =
        dlsym(RTLD_NEXT, "cuMemcpy");
    if (!real_copy) abort();
    CUresult result = real_copy(dst, src, size);
    if (getenv("TEST_CORRUPT_DATA") && result == CUDA_SUCCESS && size > 0) {
        ((unsigned char *)dst)[size - 1] ^= 1;
        fprintf(stderr, "INJECT: corrupted last byte of %zu-byte copy\n", size);
    }
    return result;
}
